INSERT INTO `call_for_proposal` VALUES (8,NULL,7,'<h2><span style=\"font-family:Times New Roman,Times,serif\">Cautionary Notes: Proposals should be: </span></h2>\r\n\r\n<ul>\r\n	<li>\r\n	<p><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:12pt\">No longer than 20 pages including cover page and reference </span></span></p>\r\n	</li>\r\n	<li>\r\n	<p><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:12pt\">Conceived by multidisciplinary teams </span></span></p>\r\n	</li>\r\n	<li>\r\n	<p><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:12pt\">Project proposals that involve Ph.D. and Masters students are highly encouraged </span></span></p>\r\n	</li>\r\n	<li>\r\n	<p><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:12pt\">Reasonable budget </span></span></p>\r\n	</li>\r\n	<li>\r\n	<p><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:12pt\">Feasibility of the project in terms of timeframe</span></span></p>\r\n	</li>\r\n	<li>\r\n	<p><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:12pt\">One person can serve as a PI only in 1 project, </span></span></p>\r\n	</li>\r\n	<li>\r\n	<p><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:12pt\">Only and the PI should be able to defend the project her/himself</span></span></p>\r\n	</li>\r\n	<li>\r\n	<p><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:12pt\">Declaration/signature of every team member must be attached to the Concept Note up on submission.</span></span></p>\r\n	</li>\r\n	<li>\r\n	<p><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:12pt\">If the proposal accepted for grant funding, </span></span></p>\r\n\r\n	<ol style=\"list-style-type:lower-alpha\">\r\n		<li>\r\n		<p><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:12pt\">The PI is required to sign a binding agreement with the office of research and academic chief directorate. </span></span></p>\r\n		</li>\r\n		<li>\r\n		<p><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:12pt\">CVs of all members should be submitted using a special format prepared by the office for this purpose (<strong>available in our office</strong>).</span></span></p>\r\n		</li>\r\n		<li>\r\n		<p><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:12pt\">Data collection and data processing agreement should be signed between the PI and Data collectors/Lab technologists/ Data clerk etc. </span></span></p>\r\n		</li>\r\n	</ol>\r\n	</li>\r\n</ul>\r\n\r\n<p><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:18px\">Important Eligibility Requirements:</span><br />\r\n<span style=\"font-size:12pt\">Failure to meet the following criteria will result in automatic rejection of the Concept Notes.</span></span></p>\r\n\r\n<ol>\r\n	<li>\r\n	<p><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:12pt\">If the entire research team or anyone of the team members has been granted:</span></span></p>\r\n\r\n	<ol style=\"list-style-type:lower-alpha\">\r\n		<li>\r\n		<p><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:12pt\">Mega research award in 2009, 2010 &amp; 2011 EC as a <strong>PI</strong>, an evidence of at least one publication from the research project must be shown.</span></span></p>\r\n		</li>\r\n		<li>\r\n		<p><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:12pt\">Mega research award in 2012 EC, as a <strong>PI, </strong>an evidence of at least one publication/or accepted Manuscript from the mega research must be shown.</span></span></p>\r\n		</li>\r\n		<li>\r\n		<p><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:12pt\">Mega research award in 2013 EC and completed the project, a full terminal report must be presented by the <strong>PI</strong>. </span></span></p>\r\n		</li>\r\n	</ol>\r\n	</li>\r\n</ol>\r\n\r\n<p><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:18px\">Outline of the proposals</span><br />\r\n<span style=\"font-size:14px\">&nbsp;&nbsp;&nbsp; 1) Title of the proposed Project<br />\r\n&nbsp;&nbsp;&nbsp; 2) Background and Rationale<br />\r\n&nbsp;&nbsp;&nbsp; 3) Project Goals and Objectives<br />\r\n&nbsp;&nbsp;&nbsp; 4) Methodology<br />\r\n&nbsp;&nbsp;&nbsp; 5) Research Project team<br />\r\n&nbsp;&nbsp;&nbsp; 6) Capacity building (inclusion of PhD and/or MSc students)<br />\r\n&nbsp;&nbsp;&nbsp; 7) Research output/outcome<br />\r\n&nbsp;&nbsp;&nbsp; 8) Ethical considerations<br />\r\n&nbsp;&nbsp;&nbsp; 9) Timeline (feasibility in one year)<br />\r\n&nbsp;&nbsp;&nbsp; 10) Budget (outline just major line items and gross budget, detailed breakdown is not required at this stage)</span></span></p>\r\n\r\n<p><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:14pt\"><strong>Submission</strong></span></span></p>\r\n\r\n<p><span style=\"font-size:14px\"><span style=\"font-family:Times New Roman,Times,serif\">Proposals</span><span style=\"font-family:Times New Roman,Times,serif\"> </span><span style=\"font-family:Times New Roman,Times,serif\">must</span><span style=\"font-family:Times New Roman,Times,serif\"> be submitted in soft copy (Word file) via </span><span style=\"font-family:Times New Roman,Times,serif\"><strong>only JU mail</strong></span><span style=\"font-family:Times New Roman,Times,serif\"> of the Applicant (</span><span style=\"font-family:Times New Roman,Times,serif\"><strong>PI</strong></span><span style=\"font-family:Times New Roman,Times,serif\">) and three hard copies to </span><span style=\"font-family:Times New Roman,Times,serif\">our office within the given time. </span></span></p>','2021-11-15 00:00:00','<p>We would like to invite interested academic staff to submit proposals on competitive mega<br />\r\nresearch project for the year 2021/22 (2014 E.C.).</p>','2021-11-11 16:24:42',NULL,'Mega research','<p>Call for Mega Research Project Proposals<br />\r\nJimma University Institute of Health (JUIH)</p>','4aaa770ad2964593e7688af098e8cc97',NULL,0,NULL,0,'Jimma University',0,'2021-11-16','2021-12-15','2021-12-17','2021-12-20',6,0,'2021-11-11 16:25:45',0,NULL,NULL),(9,17,4,'<h2><strong><span style=\"font-size:18px\"><span style=\"font-family:Times New Roman,Times,serif\">Cautionary Notes: Proposals should be: </span></span></strong></h2>\r\n\r\n<ul>\r\n	<li>\r\n	<p><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:12pt\">No longer than 20 pages including cover page and reference </span></span></p>\r\n	</li>\r\n	<li>\r\n	<p><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:12pt\">Conceived by multidisciplinary teams </span></span></p>\r\n	</li>\r\n	<li>\r\n	<p><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:12pt\">Project proposals that involve Ph.D. and Masters students are highly encouraged </span></span></p>\r\n	</li>\r\n	<li>\r\n	<p><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:12pt\">Reasonable budget </span></span></p>\r\n	</li>\r\n	<li>\r\n	<p><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:12pt\">Feasibility of the project in terms of timeframe</span></span></p>\r\n	</li>\r\n	<li>\r\n	<p><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:12pt\">One person can serve as a PI only in 1 project, </span></span></p>\r\n	</li>\r\n	<li>\r\n	<p><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:12pt\">Only and the PI should be able to defend the project her/himself</span></span></p>\r\n	</li>\r\n	<li>\r\n	<p><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:12pt\">Declaration/signature of every team member must be attached to the Concept Note up on submission.</span></span></p>\r\n	</li>\r\n	<li>\r\n	<p><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:12pt\">If the proposal accepted for grant funding, </span></span></p>\r\n\r\n	<ol style=\"list-style-type:lower-alpha\">\r\n		<li>\r\n		<p><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:12pt\">The PI is required to sign a binding agreement with the office of research and academic chief directorate. </span></span></p>\r\n		</li>\r\n		<li>\r\n		<p><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:12pt\">CVs of all members should be submitted using a special format prepared by the office for this purpose (<strong>available in our office</strong>).</span></span></p>\r\n		</li>\r\n		<li>\r\n		<p><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:12pt\">Data collection and data processing agreement should be signed between the PI and Data collectors/Lab technologists/ Data clerk etc. </span></span></p>\r\n		</li>\r\n	</ol>\r\n	</li>\r\n</ul>\r\n\r\n<p><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:18px\">Important Eligibility Requirements:</span><br />\r\n<span style=\"font-size:12pt\">Failure to meet the following criteria will result in automatic rejection of the Concept Notes.</span></span></p>\r\n\r\n<ol>\r\n	<li>\r\n	<p><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:12pt\">If the entire research team or anyone of the team members has been granted:</span></span></p>\r\n\r\n	<ol style=\"list-style-type:lower-alpha\">\r\n		<li>\r\n		<p><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:12pt\">Mega research award in 2009, 2010 &amp; 2011 EC as a <strong>PI</strong>, an evidence of at least one publication from the research project must be shown.</span></span></p>\r\n		</li>\r\n		<li>\r\n		<p><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:12pt\">Mega research award in 2012 EC, as a <strong>PI, </strong>an evidence of at least one publication/or accepted Manuscript from the mega research must be shown.</span></span></p>\r\n		</li>\r\n		<li>\r\n		<p><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:12pt\">Mega research award in 2013 EC and completed the project, a full terminal report must be presented by the <strong>PI</strong>. </span></span></p>\r\n		</li>\r\n	</ol>\r\n	</li>\r\n</ol>\r\n\r\n<p><span style=\"font-size:16px\"><span style=\"font-family:Times New Roman,Times,serif\"><strong>Outline of the proposals</strong><br />\r\n&nbsp;&nbsp;&nbsp; 1) Title of the proposed Project<br />\r\n&nbsp;&nbsp;&nbsp; 2) Background and Rationale<br />\r\n&nbsp;&nbsp;&nbsp; 3) Project Goals and Objectives<br />\r\n&nbsp;&nbsp;&nbsp; 4) Methodology<br />\r\n&nbsp;&nbsp;&nbsp; 5) Research Project team<br />\r\n&nbsp;&nbsp;&nbsp; 6) Capacity building (inclusion of PhD and/or MSc students)<br />\r\n&nbsp;&nbsp;&nbsp; 7) Research output/outcome<br />\r\n&nbsp;&nbsp;&nbsp; 8) Ethical considerations<br />\r\n&nbsp;&nbsp;&nbsp; 9) Timeline (feasibility in one year)<br />\r\n&nbsp;&nbsp;&nbsp; 10) Budget (outline just major line items and gross budget, detailed breakdown is not required at this stage)</span></span></p>\r\n\r\n<p><span style=\"font-family:Times New Roman,Times,serif\"><span style=\"font-size:14pt\"><strong>Submission</strong></span></span></p>\r\n\r\n<p><span style=\"font-size:16px\"><span style=\"font-family:Times New Roman,Times,serif\">Proposals<span style=\"font-family:Times New Roman,Times,serif\"> </span>must</span><span style=\"font-family:Times New Roman,Times,serif\"> be submitted in soft copy (Word file) via </span><span style=\"font-family:Times New Roman,Times,serif\"><strong>only JU Research Portal&nbsp;</strong></span><span style=\"font-family:Times New Roman,Times,serif\"> of the Applicant (</span><span style=\"font-family:Times New Roman,Times,serif\"><strong>PI</strong></span><span style=\"font-family:Times New Roman,Times,serif\">) . </span></span></p>','2021-11-19 00:00:00','<p><span style=\"font-size:16px\">We would like to invite interested academic staff to submit proposals on competitive mega research project for the year 2021/22 (2014 E.C.).</span></p>\r\n\r\n<p>&nbsp;</p>','2021-11-11 19:26:00',NULL,'1','<p>&nbsp;Call for Mega Research Project Proposals<br />\r\nJimma University Institute of Health (JUIH)</p>','869414e967f659dfad3ab76bd6571074',NULL,0,NULL,0,'Jimma University',0,'2021-11-17','2021-12-20','2021-12-20','2022-01-20',1728,1,'2021-11-11 16:27:36',0,NULL,NULL),(13,6,4,'<h2><span style=\"font-size:14pt\"><span style=\"font-family:Cambria,&quot;serif&quot;\"><strong><em><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\">Cautionary Notes: Proposals should be: </span></span></em></strong></span></span></h2>\r\n\r\n<ul>\r\n	<li><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\">Full length proposal with cover page and reference (APA)</span></span></span></li>\r\n	<li><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\">Conceived by multidisciplinary teams which aims specific objectives</span></span></span></li>\r\n	<li><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\">Project proposals Must Accommodate at list <strong>one Ph.D</strong>. or <strong>two Masters</strong> students </span></span></span></li>\r\n	<li><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\">Reasonable and detailed budget </span></span></span></li>\r\n	<li><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\">Feasibility of the project in terms of timeframe</span></span></span></li>\r\n	<li><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\">One person can serve as a PI only in 1 project, </span></span></span></li>\r\n	<li><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\">Only the PI should be able to defend the project her/himself with presence of CO-PIs</span></span></span></li>\r\n	<li><span style=\"font-size:12pt\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\"><span style=\"font-size:11.0pt\">Declaration/signature of every team member must be attached in separate file up on submission and need to be confirmed using the online system application by each CO-PI. </span></span></span></li>\r\n	<li><span style=\"font-size:12pt\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\"><span style=\"font-size:11.0pt\">If the proposal accepted for grant funding, </span></span></span>\r\n	<ol style=\"list-style-type:lower-alpha\">\r\n		<li><span style=\"font-size:12pt\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\"><span style=\"font-size:11.0pt\">The PI is required to sign a binding agreement with the office of research and academic chief directorate. </span></span></span></li>\r\n		<li><span style=\"font-size:12pt\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\"><span style=\"font-size:11.0pt\">CVs of all members should be submitted using a special format prepared by the office for this purpose (<strong>available in our office</strong>).</span></span></span></li>\r\n		<li><span style=\"font-size:12pt\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\"><span style=\"font-size:11.0pt\">Data collection and data processing agreement should be signed between the PI and Data collectors/Lab technologists/ Data clerk etc. and submitted before execution of the project. </span></span></span></li>\r\n	</ol>\r\n	</li>\r\n</ul>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><span style=\"font-size:12pt\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\"><strong><em>Important Eligibility </em></strong><strong><em>Requirements</em></strong><strong><em>: </em></strong></span></span></p>\r\n\r\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\">Failure to meet the following criteria will result in automatic rejection of the Concept Notes.</span></span></span></p>\r\n\r\n<ol>\r\n	<li><span style=\"font-size:12pt\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\"><span style=\"font-size:11.0pt\">If the entire research team or anyone of the team members has been granted:</span></span></span>\r\n\r\n	<ol style=\"list-style-type:lower-alpha\">\r\n		<li><span style=\"font-size:12pt\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\"><span style=\"font-size:11.0pt\">Mega research award in 2009- 2012 EC as a <strong>PI</strong>, an evidence of at least one publication from the research project must be shown.</span></span></span></li>\r\n		<li><span style=\"font-size:12pt\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\"><span style=\"font-size:11.0pt\">Mega research award in 2013 EC, as a <strong>PI, </strong>an evidence of at least one publication/or accepted Manuscript from the mega research/special grant must be shown.</span></span></span></li>\r\n		<li><span style=\"font-size:12pt\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\"><span style=\"font-size:11.0pt\">Mega research award in 2014 EC as a PI and Co-PI, must submit guaranty letter for terminal report submission before August 22 with two prepared manuscript for publication. </span></span></span></li>\r\n	</ol>\r\n	</li>\r\n</ol>\r\n\r\n<p><span style=\"font-size:12pt\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\"><strong><span style=\"font-size:11.0pt\">Outline of the proposals </span></strong></span></span></p>\r\n\r\n<ol>\r\n	<li><span style=\"font-size:12pt\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\"><span style=\"font-size:10.0pt\">Title of the proposed Project</span></span></span></li>\r\n	<li><span style=\"font-size:12pt\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\"><span style=\"font-size:10.0pt\">Background and Rationale </span></span></span></li>\r\n	<li><span style=\"font-size:12pt\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\"><span style=\"font-size:10.0pt\">Project Goals and Objectives</span></span></span></li>\r\n	<li><span style=\"font-size:12pt\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\"><span style=\"font-size:10.0pt\">Methodology </span></span></span></li>\r\n	<li><span style=\"font-size:12pt\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\"><span style=\"font-size:10.0pt\">Research Project team</span></span></span></li>\r\n	<li><span style=\"font-size:12pt\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\"><span style=\"font-size:10.0pt\">Capacity building PLAN (inclusion of PhD and/or MSc students)</span></span></span></li>\r\n	<li><span style=\"font-size:12pt\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\"><span style=\"font-size:10.0pt\">Research output/outcome</span></span></span></li>\r\n	<li><span style=\"font-size:12pt\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\"><span style=\"font-size:10.0pt\">Ethical considerations</span></span></span></li>\r\n	<li><span style=\"font-size:12pt\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\"><span style=\"font-size:10.0pt\">Timeline (feasibility in one year)</span></span></span></li>\r\n	<li><span style=\"font-size:12pt\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\"><span style=\"font-size:10.0pt\">Budget (detailed breakdown is required)</span></span></span></li>\r\n</ol>\r\n\r\n<p><span style=\"font-size:12pt\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\"><strong>Submission</strong></span></span></p>\r\n\r\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\">Proposals</span> <span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\">must</span><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\"> be submitted in soft copy (Word file) via <strong>only <a href=\"https://research.ju.edu.et\" style=\"color:blue; text-decoration:underline\">https://research.ju.edu.et</a> </strong>of the Applicant (<strong>PI</strong>) </span><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\">without list of any researchers! <strong>No need to indicate </strong>any information of <strong>Co-PI </strong>and PI in the files attched as proposal. </span></span></span></p>\r\n\r\n<p><strong><em>&nbsp;</em></strong></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><strong><em><span style=\"font-size:14.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\">NB</span></span></em></strong><strong><em><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\">:</span></span></em></strong><em> </em></span></span></p>\r\n\r\n<ul>\r\n	<li style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><em><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\">A <strong>ONE PAGE</strong> Letter of Intent and graphical conceptual frame work is encouraged to be submitted along the application in separate file.</span></span></em></span></span></li>\r\n	<li style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><em><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\">Plagiarism must be less than 1<strong>5 present</strong> in order to avoid automatic rejection of the submission. </span></span></em></span></span></li>\r\n	<li style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><em><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\">If any of the CO-PI missed conforming authorship of the proposal via the system, it will be listed under automatic <strong>rejection Bucket</strong>.</span></span></em></span></span></li>\r\n	<li style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><em><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\">We will not be <strong>sponsoring any COVID</strong> related concept proposals in this call as it is addressed by other grant fund in the institute. </span></span></em></span></span></li>\r\n	<li style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><em><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\">&nbsp;Any <strong>Ph.D. Student</strong> involved as a CO-PI in the proposal, He/ she must fulfil the following criteria:</span></span></em></span></span></li>\r\n</ul>\r\n\r\n<ul>\r\n	<li style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><em><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\">The student must be a staff member of Jimma University in affiliation</span></span></em></span></span></li>\r\n	<li style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><em><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\">He/she must be completed Ph.D. proposal defence and obtained IRB clearance from the Institute/ National</span></span></em></span></span></li>\r\n	<li style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><em><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\">Objectives assigned to, must be in line with his/her Ph.D. proposal objective/objectives </span></span></em></span></span></li>\r\n</ul>\r\n\r\n<ul>\r\n	<li style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><em><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\">Any research proposals &nbsp;aimed enhancing the capacity of institutional research &nbsp;laboratories and which also includes Ph.D. and M.Sc. students are highly encouraged </span></span></em></span></span></li>\r\n</ul>\r\n\r\n<p style=\"text-align:justify\">&nbsp;</p>\r\n\r\n<p style=\"margin-left:48px; text-align:center\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><strong><em><span style=\"font-size:14.0pt\"><span style=\"font-family:&quot;Californian FB&quot;,&quot;serif&quot;\">Research is essentially unfinished unless the findings are synthesised and applied in practice to improve the population health</span></span></em></strong></span></span></p>\r\n\r\n<p style=\"margin-left:48px; text-align:center\">&nbsp;</p>\r\n\r\n<p>&nbsp;</p>','2022-05-31 00:00:00','<p style=\"text-align:center\"><span style=\"font-size:20px\"><strong><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\">We would like to invite interested academic staff to submit </span><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\">proposals on competitive mega research project for the year 2022/23 (2015 E.C.).</span></span></strong></span></p>','2022-03-28 16:56:30',NULL,'1','<p style=\"text-align:center\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><strong><span style=\"font-size:18.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\"><span style=\"color:#000099\">Call for Mega Research Project Proposals</span></span></span></strong></span></span></p>\r\n\r\n<p style=\"text-align:center\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><strong><span style=\"font-size:18.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\"><span style=\"color:#000099\">Jimma University Institute of Health (JUIH)</span></span></span></strong></span></span></p>','f2e333380dd61765064e65733a57b479',NULL,0,NULL,0,'Jimma University',0,'2022-06-01','2022-06-21','2022-06-30','2022-07-15',645,1,'2022-03-28 16:56:53',0,'Call For Proposal Attachement 2a60603fecd51b3cee22e655dc486df1.pdf',NULL),(14,6,4,'<h2><span style=\"font-size:14pt\"><span style=\"font-family:Cambria,&quot;serif&quot;\"><strong><em><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\">Cautionary Notes: Proposals should be: </span></span></em></strong></span></span></h2>\r\n\r\n<ul>\r\n	<li><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\">Full length proposal with cover page and reference (APA)</span></span></span></li>\r\n	<li><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\">Conceived by multidisciplinary teams which aims specific objectives</span></span></span></li>\r\n	<li><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\">Project proposals that involve &nbsp;Ph.D. and Masters students are highly encouraged </span></span></span></li>\r\n	<li><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\">Reasonable and detailed budget </span></span></span></li>\r\n	<li><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\">Feasibility of the project in terms of timeframe</span></span></span></li>\r\n	<li><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\">One person can serve as a <strong>PI only in 1</strong> project, and as a <strong>CO-PI in one</strong> project</span></span></span></li>\r\n	<li><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\">Only and the PI should be able to defend the project herself</span></span></span></li>\r\n	<li><span style=\"font-size:12pt\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\"><span style=\"font-size:11.0pt\">Declaration/signature of every team member must be attached to the Concept Note up on submission and need to be confirmed using the online system application. </span></span></span></li>\r\n	<li><span style=\"font-size:12pt\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\"><span style=\"font-size:11.0pt\">If the proposal accepted for grant funding, </span></span></span>\r\n	<ol style=\"list-style-type:lower-alpha\">\r\n		<li><span style=\"font-size:12pt\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\"><span style=\"font-size:11.0pt\">The PI is required to sign a binding agreement with the office of research and academic chief directorate. </span></span></span></li>\r\n		<li><span style=\"font-size:12pt\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\"><span style=\"font-size:11.0pt\">CVs of all members should be submitted using a special format prepared by the office for this purpose (<strong>available in our office</strong>).</span></span></span></li>\r\n		<li><span style=\"font-size:12pt\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\"><span style=\"font-size:11.0pt\">Data collection and data processing agreement should be signed between the PI and Data collectors/Lab technologists/ Data clerk etc. and submitted before execution of the project. (Data collectors/Lab technologists/ Data clerk etc. must be <strong>only Female</strong>) </span></span></span></li>\r\n	</ol>\r\n	</li>\r\n</ul>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><span style=\"font-size:12pt\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\"><strong><em>Important Eligibility </em></strong><strong><em>Requirements</em></strong><strong><em>: </em></strong></span></span></p>\r\n\r\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\">Failure to meet the following criteria will result in automatic rejection of the Concept Notes.</span></span></span></p>\r\n\r\n<ol>\r\n	<li><span style=\"font-size:12pt\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\"><span style=\"font-size:11.0pt\">If the entire research team or anyone of the team members has been granted:</span></span></span>\r\n\r\n	<ol style=\"list-style-type:lower-alpha\">\r\n		<li><span style=\"font-size:12pt\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\"><span style=\"font-size:11.0pt\">Mega research award in 2009- 2012 EC as a <strong>PI</strong>, an evidence of at least one publication from the research project must be shown.</span></span></span></li>\r\n		<li><span style=\"font-size:12pt\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\"><span style=\"font-size:11.0pt\">Mega research award in 2013 EC, as a <strong>PI, </strong>an evidence of at least one publication/or accepted Manuscript from the mega research/special grant must be shown.</span></span></span></li>\r\n		<li><span style=\"font-size:12pt\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\"><span style=\"font-size:11.0pt\">Mega research award in 2014 EC as a PI and Co-PI, must submit guaranty letter for terminal report submission before August 22 with two prepared manuscript for publication. </span></span></span></li>\r\n	</ol>\r\n	</li>\r\n</ol>\r\n\r\n<p><span style=\"font-size:12pt\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\"><strong><span style=\"font-size:11.0pt\">Outline of the proposals </span></strong></span></span></p>\r\n\r\n<ol>\r\n	<li><span style=\"font-size:12pt\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\"><span style=\"font-size:10.0pt\">Title of the proposed Project</span></span></span></li>\r\n	<li><span style=\"font-size:12pt\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\"><span style=\"font-size:10.0pt\">Background and Rationale </span></span></span></li>\r\n	<li><span style=\"font-size:12pt\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\"><span style=\"font-size:10.0pt\">Project Goals and Objectives</span></span></span></li>\r\n	<li><span style=\"font-size:12pt\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\"><span style=\"font-size:10.0pt\">Methodology </span></span></span></li>\r\n	<li><span style=\"font-size:12pt\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\"><span style=\"font-size:10.0pt\">Research Project team</span></span></span></li>\r\n	<li><span style=\"font-size:12pt\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\"><span style=\"font-size:10.0pt\">Capacity building (inclusion of PhD and/or MSc students)</span></span></span></li>\r\n	<li><span style=\"font-size:12pt\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\"><span style=\"font-size:10.0pt\">Research output/outcome</span></span></span></li>\r\n	<li><span style=\"font-size:12pt\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\"><span style=\"font-size:10.0pt\">Ethical considerations</span></span></span></li>\r\n	<li><span style=\"font-size:12pt\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\"><span style=\"font-size:10.0pt\">Timeline (feasibility in one year)</span></span></span></li>\r\n	<li><span style=\"font-size:12pt\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\"><span style=\"font-size:10.0pt\">Budget (detailed breakdown is required)</span></span></span></li>\r\n</ol>\r\n\r\n<p><span style=\"font-size:12pt\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\"><strong>Submission</strong></span></span></p>\r\n\r\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\">Proposals</span> <span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\">must</span><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\"> be submitted in soft copy (Word file) via <strong>only <a href=\"https://research.ju.edu.et\" style=\"color:blue; text-decoration:underline\">https://research.ju.edu.et</a> </strong>of the Applicant (<strong>PI</strong>)</span><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\">. No need of indicating any information of Co-PI and PI in the files attched as proposal. </span></span></span></p>\r\n\r\n<p><strong><em>&nbsp;</em></strong></p>\r\n\r\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><strong><em><span style=\"font-size:14.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\">NB</span></span></em></strong><strong><em><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\">:</span></span></em></strong><em> </em></span></span></p>\r\n\r\n<ul>\r\n	<li style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><em><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\">A <strong>ONE PAGE</strong> Letter of Intent and graphical conceptual frame work is encouraged to be submitted along the application in separate file.</span></span></em></span></span></li>\r\n	<li style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><em><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\">Plagiarism must be less than 1<strong>5 present</strong> in order to avoid automatic rejection of the submission. </span></span></em></span></span></li>\r\n	<li style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><em><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\">If any of the CO-PI missed conforming authorship of the proposal via the system, it will be listed under automatic <strong>rejection Bucket</strong>.</span></span></em></span></span></li>\r\n	<li style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><em><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\">We will not be sponsoring any COVID related concept proposals in this call</span></span></em></span></span></li>\r\n	<li style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><em><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\">&nbsp;Any <strong>Ph.D. Student</strong> involved as a CO-PI in the proposal, He/ she must fulfil the following criteria:</span></span></em></span></span></li>\r\n</ul>\r\n\r\n<ul>\r\n	<li style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><em><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\">The student must be a staff member of Jimma University in affiliation</span></span></em></span></span></li>\r\n	<li style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><em><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\">He/she must be completed Ph.D. proposal defence and obtained IRB clearance from the Institute/ National</span></span></em></span></span></li>\r\n	<li style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><em><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\">Objectives assigned to, must be in line with his/her Ph.D. proposal objective/objectives </span></span></em></span></span></li>\r\n</ul>\r\n\r\n<ul>\r\n	<li style=\"text-align:justify\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><em><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\">Experimental and Lab based proposals aimed enhancing the capacity of institutional&nbsp; laboratories and which includes Ph.D. and M.Sc. students are highly encouraged </span></span></em></span></span></li>\r\n</ul>\r\n\r\n<p style=\"text-align:justify\">&nbsp;</p>\r\n\r\n<p style=\"margin-left:48px; text-align:center\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><strong><em><span style=\"font-size:14.0pt\"><span style=\"font-family:&quot;Californian FB&quot;,&quot;serif&quot;\">Research is essentially unfinished unless the findings are synthesised and applied in practice to improve the population health</span></span></em></strong></span></span></p>','2022-05-31 00:00:00','<p><strong><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\">We would like to invite interested <em>WOMEN</em> academic staff to submit </span><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\">proposals on competitive mega research project for the year 2022/23 (2015E.C.).</span></span></span></strong></p>','2022-03-28 17:04:17',NULL,'1','<p style=\"text-align:center\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><strong><span style=\"font-size:18.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\"><span style=\"color:#000099\">Call for Mega Research Project Proposals</span></span></span></strong></span></span></p>\r\n\r\n<p style=\"text-align:center\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><strong><span style=\"font-size:18.0pt\"><span style=\"font-family:&quot;Times New Roman&quot;,&quot;serif&quot;\"><span style=\"color:#000099\">Jimma University Institute of Health (JUIH) for WOMEN</span></span></span></strong></span></span></p>','3dba2107b94c9b825db2bd9cb473d0a6',NULL,0,NULL,0,'Jimma University',0,'2022-06-01','2022-06-21','2022-06-30','2022-07-15',312,1,'2022-03-28 17:04:33',0,'Call For Proposal Attachement 8146586bce56f246d6407c77e42d88eb.pdf',NULL);
