INSERT INTO `guideline_for_reviewer` VALUES (1,NULL,4,'Guideline For reviewers','<h4>&nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; &nbsp; <span style=\"font-size:11pt\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><u><span style=\"font-size:20.0pt\"><span style=\"font-family:&quot;Californian FB&quot;,&quot;serif&quot;\">Jimma university</span></span></u></span></span></h4>\r\n\r\n<p style=\"text-align:center\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><u><span style=\"font-size:20.0pt\"><span style=\"font-family:&quot;Californian FB&quot;,&quot;serif&quot;\">Institute of health</span></span></u></span></span></p>\r\n\r\n<p style=\"text-align:center\"><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><u><span style=\"font-size:20.0pt\"><span style=\"font-family:&quot;Californian FB&quot;,&quot;serif&quot;\">Mega research project proposal evaluation criteria</span></span></u></span></span></p>\r\n\r\n<p>&nbsp;</p>\r\n\r\n<p><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><u><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Californian FB&quot;,&quot;serif&quot;\">ASSESSMENT GUIDELINES</span></span></u></span></span></p>\r\n\r\n<ol>\r\n	<li><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Californian FB&quot;,&quot;serif&quot;\">This instrument contains 12 key areas. Each section may have one or more sub-sections referring to research aspects to be evaluated. </span></span></span></span></li>\r\n	<li><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Californian FB&quot;,&quot;serif&quot;\">For each aspect evaluated, please give a rating/points out of the total mark designated to the specified criteria. </span></span></span></span></li>\r\n	<li><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Californian FB&quot;,&quot;serif&quot;\">Add all the marks to get the total score out of 150 points.</span></span></span></span></li>\r\n</ol>\r\n\r\n<p style=\"margin-left:27px\">&nbsp;</p>\r\n\r\n<table align=\"center\" cellspacing=\"0\" class=\"MsoTableGrid\" style=\"border-collapse:collapse; border:none\">\r\n	<tbody>\r\n		<tr>\r\n			<td style=\"border-bottom:1px solid black; border-left:1px solid black; border-right:1px solid black; border-top:1px solid black; vertical-align:top; width:536px\">\r\n			<ol>\r\n				<li><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><strong><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Californian FB&quot;,&quot;serif&quot;\">TITLE </span></span></strong></span></span></li>\r\n			</ol>\r\n			</td>\r\n			<td style=\"border-bottom:1px solid black; border-left:none; border-right:1px solid black; border-top:1px solid black; vertical-align:top; width:80px\">\r\n			<p><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><strong><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Californian FB&quot;,&quot;serif&quot;\">5 points</span></span></strong></span></span></p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"border-bottom:1px solid black; border-left:1px solid black; border-right:1px solid black; border-top:none; vertical-align:top; width:536px\">\r\n			<ul>\r\n				<li><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Californian FB&quot;,&quot;serif&quot;\">Is the title appropriate to problem investigated and Clear reflection of project content: </span></span></span></span></li>\r\n				<li><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Californian FB&quot;,&quot;serif&quot;\">Is the&nbsp; title carries the exact/appropriate meaning and covers the study carried out </span></span></span></span></li>\r\n				<li><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Californian FB&quot;,&quot;serif&quot;\">Is the title not too short or not too long?</span></span></span></span></li>\r\n			</ul>\r\n\r\n			<p><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\">&nbsp;</span></span></p>\r\n			</td>\r\n			<td style=\"border-bottom:1px solid black; border-left:none; border-right:1px solid black; border-top:none; vertical-align:top; width:80px\">\r\n			<p>&nbsp;</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"border-bottom:1px solid black; border-left:1px solid black; border-right:1px solid black; border-top:none; vertical-align:top; width:536px\">\r\n			<ol start=\"2\">\r\n				<li><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><strong><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Californian FB&quot;,&quot;serif&quot;\">ABSTRACT/ SUMMERY </span></span></strong></span></span></li>\r\n			</ol>\r\n\r\n			<p>&nbsp;</p>\r\n			</td>\r\n			<td style=\"border-bottom:1px solid black; border-left:none; border-right:1px solid black; border-top:none; vertical-align:top; width:80px\">\r\n			<p><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><strong><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Californian FB&quot;,&quot;serif&quot;\">5 points</span></span></strong></span></span></p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"border-bottom:1px solid black; border-left:1px solid black; border-right:1px solid black; border-top:none; vertical-align:top; width:536px\">\r\n			<ul>\r\n				<li><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Californian FB&quot;,&quot;serif&quot;\">Is the question or issue clearly stated in the abstract?</span></span></span></span></li>\r\n				<li><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Californian FB&quot;,&quot;serif&quot;\">Is the significance of the work clearly stated?</span></span></span></span></li>\r\n			</ul>\r\n			</td>\r\n			<td style=\"border-bottom:1px solid black; border-left:none; border-right:1px solid black; border-top:none; vertical-align:top; width:80px\">\r\n			<p>&nbsp;</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"border-bottom:1px solid black; border-left:1px solid black; border-right:1px solid black; border-top:none; vertical-align:top; width:536px\">\r\n			<ol start=\"3\">\r\n				<li><span style=\"font-size:11pt\"><span style=\"background-color:white\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><strong><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Californian FB&quot;,&quot;serif&quot;\"><span style=\"color:#01172f\">&nbsp;INTRODUCTION/BACKGROUND/RATIONALE/SIGNIFICANCE:</span></span></span></strong></span></span></span></li>\r\n			</ol>\r\n			</td>\r\n			<td style=\"border-bottom:1px solid black; border-left:none; border-right:1px solid black; border-top:none; vertical-align:top; width:80px\">\r\n			<p><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><strong><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Californian FB&quot;,&quot;serif&quot;\">20 points</span></span></strong></span></span></p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"border-bottom:1px solid black; border-left:1px solid black; border-right:1px solid black; border-top:none; height:232px; vertical-align:top; width:536px\">\r\n			<ul>\r\n				<li><span style=\"font-size:11pt\"><span style=\"background-color:white\"><span style=\"color:#3e3e3e\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Californian FB&quot;,&quot;serif&quot;\">Is the problem or opportunity to be addressed by the proposed project is clearly identified, outlined, well defined and delineated?</span></span></span></span></span></span></li>\r\n				<li><span style=\"font-size:11pt\"><span style=\"background-color:white\"><span style=\"color:#3e3e3e\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Californian FB&quot;,&quot;serif&quot;\">Does the project address a regional or national problem(s)?and in line with the national thematic areas</span></span></span></span></span></span></li>\r\n				<li><span style=\"font-size:11pt\"><span style=\"background-color:white\"><span style=\"color:#3e3e3e\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Californian FB&quot;,&quot;serif&quot;\">Does the literature review clearly identify what is known about the problem or the proposed innovation and identify gaps?</span></span></span></span></span></span></li>\r\n				<li><span style=\"font-size:11pt\"><span style=\"background-color:white\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Californian FB&quot;,&quot;serif&quot;\">Does the proposal demonstrate thorough and current understanding and knowledge of the peer reviewed literature related to the topic? </span></span></span></span></span></li>\r\n				<li><span style=\"font-size:11pt\"><span style=\"background-color:white\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Californian FB&quot;,&quot;serif&quot;\"><span style=\"color:#3e3e3e\">Is there a conceptual framework or theoretical perspective identified to support the work?</span></span></span></span></span></span></li>\r\n				<li><span style=\"font-size:11pt\"><span style=\"background-color:white\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Californian FB&quot;,&quot;serif&quot;\">Is a theoretical framework identified and clearly described? </span></span></span></span></span></li>\r\n				<li><span style=\"font-size:11pt\"><span style=\"background-color:white\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Californian FB&quot;,&quot;serif&quot;\">Is the theoretical framework linked to the research problem/question/hypothesis? </span></span></span></span></span></li>\r\n			</ul>\r\n			</td>\r\n			<td style=\"border-bottom:1px solid black; border-left:none; border-right:1px solid black; border-top:none; height:232px; vertical-align:top; width:80px\">\r\n			<p>&nbsp;</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"border-bottom:1px solid black; border-left:1px solid black; border-right:1px solid black; border-top:none; vertical-align:top; width:536px\">\r\n			<ol start=\"4\">\r\n				<li><span style=\"font-size:11pt\"><span style=\"background-color:white\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><strong><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Californian FB&quot;,&quot;serif&quot;\">INNOVATION</span></span></strong></span></span></span></li>\r\n			</ol>\r\n			</td>\r\n			<td style=\"border-bottom:1px solid black; border-left:none; border-right:1px solid black; border-top:none; vertical-align:top; width:80px\">\r\n			<p><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><strong><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Californian FB&quot;,&quot;serif&quot;\">20 points</span></span></strong></span></span></p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"border-bottom:1px solid black; border-left:1px solid black; border-right:1px solid black; border-top:none; vertical-align:top; width:536px\">\r\n			<ul>\r\n				<li><span style=\"font-size:11pt\"><span style=\"background-color:white\"><span style=\"color:#3e3e3e\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Californian FB&quot;,&quot;serif&quot;\">Are significant aspects of the project based on an innovative or a non-traditional approach? </span></span></span></span></span></span></li>\r\n				<li><span style=\"font-size:11pt\"><span style=\"background-color:white\"><span style=\"color:#3e3e3e\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Californian FB&quot;,&quot;serif&quot;\">Does the project reflect creative thinking? </span></span></span></span></span></span></li>\r\n				<li><span style=\"font-size:11pt\"><span style=\"background-color:white\"><span style=\"color:#3e3e3e\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Californian FB&quot;,&quot;serif&quot;\">To what degree does the proposal reflect a unique approach that is new to the applicant institution or new to the entire field of study?</span></span></span></span></span></span></li>\r\n			</ul>\r\n			</td>\r\n			<td style=\"border-bottom:1px solid black; border-left:none; border-right:1px solid black; border-top:none; vertical-align:top; width:80px\">\r\n			<p>&nbsp;</p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"border-bottom:1px solid black; border-left:1px solid black; border-right:1px solid black; border-top:none; vertical-align:top; width:536px\">\r\n			<ol start=\"5\">\r\n				<li><span style=\"font-size:11pt\"><span style=\"background-color:white\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><strong><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Californian FB&quot;,&quot;serif&quot;\"><span style=\"color:#01172f\">PROJECT AIMS/OBJECTIVE/HYPOTHESIS:</span></span></span></strong></span></span></span></li>\r\n			</ol>\r\n			</td>\r\n			<td style=\"border-bottom:1px solid black; border-left:none; border-right:1px solid black; border-top:none; vertical-align:top; width:80px\">\r\n			<p><span style=\"font-size:11pt\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><strong><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Californian FB&quot;,&quot;serif&quot;\">15 Points</span></span></strong></span></span></p>\r\n			</td>\r\n		</tr>\r\n		<tr>\r\n			<td style=\"border-bottom:1px solid black; border-left:1px solid black; border-right:1px solid black; border-top:none; vertical-align:top; width:536px\">\r\n			<ul>\r\n				<li><span style=\"font-size:11pt\"><span style=\"background-color:white\"><span style=\"color:#3e3e3e\"><span style=\"font-family:Calibri,&quot;sans-serif&quot;\"><span style=\"font-size:12.0pt\"><span style=\"font-family:&quot;Californian FB&quot;,&quot;serif&quot;\">Are the projects aims/objectives/hypothesis are clearly stated, feasible, and appropriately focused and narrow?</span></span></span></span></span></span></li>\r\n				<li><span style=\"font-size:11pt\"><span style=\"background-color:white\"><span style=\"color:#3e3e3e\"><span style=\"fo