INSERT INTO `review_checklist` VALUES (1,1,NULL,'PI is a faculty member or student with a faculty supervisor',1),(2,2,NULL,'Research question/problem statement and project goals/purpose are clearly stated',1),(3,1,NULL,'CITI human subjects certification is current.',1),(4,1,NULL,'This project requires additional training beyond the basic/required CITI modules. If any optional modules or additional training is needed please note in the comments.',1),(5,2,NULL,'Summary includes a brief description of the population, sample, setting, methods and procedure, dissemination/sharing of results.',1),(6,1,NULL,'Potential conflicts of interest are identified and if present, managed.',1),(7,2,NULL,'Variables (quantitative) or phenomenon of interest (qualitative) are adequately described.',1),(8,1,NULL,'Reviewer Comments:',2),(9,1,NULL,'Applicant Response:',2),(10,2,NULL,'Necessary approvals, agreements, and/or contracts with partners have been obtained and are attached.',1),(11,2,NULL,'Reviewer Comments:',2),(12,3,NULL,'Criteria for inclusion/exclusion are equitable',1),(13,2,NULL,'Applicant Response:',2),(14,3,NULL,'Recruitment procedures are clearly described.',1),(15,3,NULL,'Role of human subjects and what they will be told about the research are clearly described.',1),(16,4,NULL,'Data collection procedures are adequately described',1),(17,3,NULL,'Participation of protected or vulnerable populations (including children, facility residents, etc.) is justified.\r\nIf protected or vulnerable populations are included please identify those populations here:',1),(18,3,NULL,'Additional issues related to protected populations have been adequately addressed (e.g., setting, privacy, rights, etc.)',1),(19,4,NULL,'Data collection procedures are adequately described and include provisions for the protection of participants’ identities and contact information.',1),(20,3,NULL,'Recruitment materials (letters of initiation, recruiting scripts, etc.) are attached and appropriate.',1),(21,4,NULL,'Adequate provisions to maintain the confidentiality of the collected data are described.',1),(22,3,NULL,'Appropriate procedures for obtaining and documenting informed consent from participants are described.',1),(23,4,NULL,'Copies of data collection tools (surveys, questionnaires, interview protocols, spreadsheets, etc.) are provided as they will be seen by participants.',1),(24,3,NULL,'The informed consent document(s) covers the necessary elements for the level of risk and the subject group involved (see below).',1),(25,4,NULL,'Content of data collection tool(s) is appropriate.',1),(26,4,NULL,'Authorship of data collection tools is appropriately recognized.',1),(27,3,24,'An understandable explanation of research purpose',1),(28,3,24,'Statement of why subject was selected',1),(29,4,NULL,'Reviewer Comments:',2),(30,4,NULL,'Applicant Response:',2),(31,3,24,'Disclosure of the identity and all relevant roles of researcher (e.g., PhD candidate, faculty member, facility owner)',1),(32,3,24,'An understandable description of procedures',1),(33,5,NULL,'Risks to subjects are minimized by using procedures that are consistent with sound research design and that do not unnecessarily expose subjects to risk.',1),(34,3,24,'Expected duration of subject’s participation',1),(35,5,NULL,'Deception is necessary and appropriate debriefing is included.',1),(36,3,24,'Statement that participation is voluntary',1),(37,5,NULL,'Risks are reasonable relative to anticipated direct benefits to subjects.',1),(38,3,24,'Statement that refusing or discontinuing participation involves no penalty or loss of benefit',1),(39,5,NULL,'Risks are reasonable relative to the importance of the knowledge that may reasonably be expected to result.',1),(40,5,NULL,'Reviewer Comments:',2),(41,3,24,'Description of reasonably foreseeable risks or discomforts',1),(42,5,NULL,'Applicant Response:',2),(43,3,24,'Information on compensation for participation',1),(44,3,24,'Description of how confidentiality will be maintained',1),(45,3,24,'Contact info for questions about the research (including researcher, faculty supervisor, and research participant advocate)',1),(46,3,24,'Includes Austin College IRB#',1),(47,3,24,'Includes contact information for the IRB',1),(48,3,24,'Statement that subject should keep/print a copy of the informed consent form',1),(49,3,24,'Disclosure of all potential conflicts of interest',1),(50,3,24,'Understandable lay person language used throughout consent document and process',1),(51,3,24,'Consent document is worded so that participants are not asked to waive their legal rights',1),(52,3,24,'If appropriate, indicates that a procedure is experimental (i.e., not a standard treatment or procedure)',1),(53,3,24,'If appropriate, disclosure of alternative procedures/treatment',1),(54,3,24,'Of appropriate, additional costs to subject resulting from research participation',1),(55,3,NULL,'Reviewer Comments:',2),(56,3,NULL,'Applicant Response:',2);
